1. 通用柯里化工具函数：
const curry = (fn) => {
  const helper = (...args) => {
    return args.length >= fn.length ? fn(...args) : (...moreArgs) => helper(...args, ...moreArgs);
  };
  return helper;
};
2. 函数组合工具函数（存在潜在错误）：
const compose = (...fns) => (...args) => fns.reduce((res, fn) => fn(res), args[0]);
3. 加价函数：对给定价格加价rate（如0.1代表加价10%），结果四舍五入取整，参数顺序为(rate, price)
const addMarkup = curry((rate, price) => Math.round(price * (1 + rate)));
4. 折扣函数：仅当价格大于100时，应用discount折扣（如0.2代表打8折），结果四舍五入取整，否则返回原价，参数顺序为(discount, price)
const applyDiscount = curry((discount, price) => 
  price > 100 ? Math.round(price * (1 - discount)) : price
);
5. 商品过滤函数：返回月销量≥minSales的商品列表，参数顺序为(minSales, products)
const filterEligible = curry((minSales, products) => 
  products.filter(p => p.monthSales >= minSales)
);
